(() => {
  'use strict';

  const clamp = (v, lo, hi) => Math.min(Math.max(v, lo), hi);

  function setup(root) {
    if (root.dataset.ivReady || typeof root.querySelector !== 'function') return;
    const stage = root.querySelector('.iv-stage');
    const canvas = root.querySelector('.iv-canvas');
    const zoomLabel = root.querySelector('[data-iv-zoom]');
    if (!stage || !canvas) return;
    root.dataset.ivReady = '1';

    const svg = canvas.querySelector('svg');
    const svgMode = !!svg;
    const min = Math.max(1, Number(root.dataset.min) || 1);
    const max = Math.max(min, Number(root.dataset.max) || 16);

    let home = null;
    let vb = null;
    if (svgMode) {
      const b = svg.viewBox && svg.viewBox.baseVal;
      if (b && b.width > 0 && b.height > 0) {
        home = { x: b.x, y: b.y, w: b.width, h: b.height };
      } else {
        const r = svg.getBoundingClientRect();
        home = { x: 0, y: 0, w: r.width || 1, h: r.height || 1 };
      }
      vb = Object.assign({}, home);
      svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
    }

    let scale = 1;
    let tx = 0;
    let ty = 0;
    const pointers = new Map();
    let pinch = null;

    const size = () => ({ w: stage.clientWidth, h: stage.clientHeight });
    const zoom = () => (svgMode ? home.w / vb.w : scale);
    const fitScale = () => {
      const s = size();
      return Math.min(s.w / vb.w, s.h / vb.h);
    };
    const local = (clientX, clientY) => {
      const r = stage.getBoundingClientRect();
      return { x: clientX - r.left, y: clientY - r.top };
    };
    const center = () => {
      const s = size();
      return { x: s.w / 2, y: s.h / 2 };
    };

    let pendingFrame = 0;
    function paint() {
      if (svgMode) {
        svg.setAttribute('viewBox', `${vb.x} ${vb.y} ${vb.w} ${vb.h}`);
      } else {
        canvas.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;
      }
      if (zoomLabel) zoomLabel.textContent = `${Math.round(zoom() * 100)}%`;
    }

    // 大 SVG 重绘代价高，按帧合并高频 pointermove / wheel
    function render() {
      if (pendingFrame) return;
      pendingFrame = requestAnimationFrame(() => {
        pendingFrame = 0;
        paint();
      });
    }

    function constrain() {
      if (svgMode) {
        vb.x = clamp(vb.x, home.x, home.x + home.w - vb.w);
        vb.y = clamp(vb.y, home.y, home.y + home.h - vb.h);
      } else {
        const s = size();
        tx = clamp(tx, s.w * (1 - scale), 0);
        ty = clamp(ty, s.h * (1 - scale), 0);
      }
    }

    function setZoom(next, px, py) {
      next = clamp(next, min, max);
      if (Math.abs(next - zoom()) < 1e-6) return;
      if (svgMode) {
        const s = size();
        const f = fitScale();
        const ox = (s.w - vb.w * f) / 2;
        const oy = (s.h - vb.h * f) / 2;
        const ux = vb.x + (px - ox) / f;
        const uy = vb.y + (py - oy) / f;
        const nw = home.w / next;
        const nh = home.h / next;
        const k = nw / vb.w;
        vb.x = ux - (ux - vb.x) * k;
        vb.y = uy - (uy - vb.y) * k;
        vb.w = nw;
        vb.h = nh;
      } else {
        const k = next / scale;
        tx = px - (px - tx) * k;
        ty = py - (py - ty) * k;
        scale = next;
      }
      constrain();
      render();
    }

    function pan(dx, dy) {
      if (svgMode) {
        const f = fitScale();
        vb.x -= dx / f;
        vb.y -= dy / f;
      } else {
        tx += dx;
        ty += dy;
      }
      constrain();
      render();
    }

    function reset() {
      if (svgMode) vb = Object.assign({}, home);
      else { scale = 1; tx = 0; ty = 0; }
      render();
    }

    stage.addEventListener('wheel', (e) => {
      e.preventDefault();
      const p = local(e.clientX, e.clientY);
      const unit = e.deltaMode === 1 ? 0.03 : 0.0015;
      setZoom(zoom() * Math.exp(-e.deltaY * unit), p.x, p.y);
    }, { passive: false });

    stage.addEventListener('dblclick', (e) => {
      const p = local(e.clientX, e.clientY);
      setZoom(zoom() * 2, p.x, p.y);
    });

    stage.addEventListener('pointerdown', (e) => {
      if (e.pointerType === 'mouse' && e.button !== 0) return;
      try { stage.setPointerCapture(e.pointerId); } catch (_) { /* noop */ }
      pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
      if (pointers.size === 2) {
        const [a, b] = Array.from(pointers.values());
        pinch = { dist: Math.hypot(a.x - b.x, a.y - b.y) || 1, zoom: zoom() };
      }
    });

    stage.addEventListener('pointermove', (e) => {
      if (!pointers.has(e.pointerId)) return;
      const prev = pointers.get(e.pointerId);
      pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
      if (pointers.size >= 2 && pinch) {
        const [a, b] = Array.from(pointers.values());
        const dist = Math.hypot(a.x - b.x, a.y - b.y) || 1;
        const mid = local((a.x + b.x) / 2, (a.y + b.y) / 2);
        setZoom(pinch.zoom * (dist / pinch.dist), mid.x, mid.y);
      } else if (pointers.size === 1) {
        pan(e.clientX - prev.x, e.clientY - prev.y);
      }
    });

    const endPointer = (e) => {
      pointers.delete(e.pointerId);
      try { stage.releasePointerCapture(e.pointerId); } catch (_) { /* noop */ }
      if (pointers.size < 2) pinch = null;
    };
    stage.addEventListener('pointerup', endPointer);
    stage.addEventListener('pointercancel', endPointer);
    stage.addEventListener('dragstart', (e) => e.preventDefault());

    const bind = (selector, fn) => {
      const el = root.querySelector(selector);
      if (el) el.addEventListener('click', fn);
    };
    bind('[data-iv-in]', () => { const c = center(); setZoom(zoom() * 1.5, c.x, c.y); });
    bind('[data-iv-out]', () => { const c = center(); setZoom(zoom() / 1.5, c.x, c.y); });
    bind('[data-iv-reset]', reset);
    bind('[data-iv-full]', () => {
      if (document.fullscreenElement) document.exitFullscreen();
      else if (root.requestFullscreen) root.requestFullscreen();
    });

    root.addEventListener('keydown', (e) => {
      const c = center();
      switch (e.key) {
        case 'ArrowLeft': pan(40, 0); break;
        case 'ArrowRight': pan(-40, 0); break;
        case 'ArrowUp': pan(0, 40); break;
        case 'ArrowDown': pan(0, -40); break;
        case '+': case '=': setZoom(zoom() * 1.5, c.x, c.y); break;
        case '-': case '_': setZoom(zoom() / 1.5, c.x, c.y); break;
        case '0': reset(); break;
        case 'Escape': if (document.fullscreenElement) document.exitFullscreen(); break;
        default: return;
      }
      e.preventDefault();
    });

    render();
  }

  const initAll = (scope) => {
    const base = scope || document;
    if (!base.querySelectorAll) return;
    base.querySelectorAll('[data-iv]').forEach(setup);
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => initAll());
  } else {
    initAll();
  }
  window.initImageViewer = initAll;
})();
